import itertools
def shop(prices, pages, x):
    best = [0] * (x + 1)
    for h, s in zip(prices, pages):
        for b in range(x, h - 1, -1): best[b] = max(best[b], best[b - h] + s)
    return best[x]
def slow(prices, pages, x): return max(sum(pages[i] for i in c) for k in range(len(prices) + 1) for c in itertools.combinations(range(len(prices)), k) if sum(prices[i] for i in c) <= x)
result = slow((4, 8, 5, 3), (5, 12, 8, 1), 10)

